test('oracleVersionAndSave (G6-A03 + G6-A04) PASSes faithful read/edit and FAILs/BLOCKs each violation', () => {
  const validRead = {
    operation: 'read',
    versionsBefore: 1,
    versionsAfterAiTurn: 1,
    revisionBefore: 'rev-1',
    revisionAfterAiTurn: 'rev-1',
    saveIntentsDuringAiTurn: 0,
  };
  assert.equal(oracleVersionAndSave(validRead).status, VERDICT.PASS);

  const validEdit = {
    operation: 'edit',
    versionsBefore: 1,
    versionsAfterAiTurn: 1,
    revisionBefore: 'rev-1',
    revisionAfterAiTurn: 'rev-1',
    saveIntentsDuringAiTurn: 0,
    versionsAfterSave: 2,
    revisionAfterSave: 'rev-2',
    aiChangeVisibleBeforeSave: true,
    aiChangeUndoableBeforeSave: true,
    saveUsedCurrentBaseRevision: true,
    // w2e2 (G708-R2-1): versions the SECOND Save added; a double Save stays a single version.
    doubleClickVersionsCreated: 0,
  };
  assert.equal(oracleVersionAndSave(validEdit).status, VERDICT.PASS);

  // BLOCKED when required fields are omitted (R1-1)
  assert.equal(oracleVersionAndSave(null).reason, 'missing_version_artifact');
  assert.equal(oracleVersionAndSave({ ...validRead, operation: undefined }).reason, 'missing_operation');
  assert.equal(oracleVersionAndSave({ ...validEdit, operation: 'unknown' }).reason, 'missing_operation');
  assert.equal(oracleVersionAndSave({ operation: 'read', versionsBefore: 1 }).reason, 'missing_version_or_revision_before_after');
  assert.equal(oracleVersionAndSave({ ...validRead, saveIntentsDuringAiTurn: undefined }).reason, 'missing_save_intents_during_ai_turn');
  assert.equal(oracleVersionAndSave({ ...validEdit, versionsAfterSave: undefined }).reason, 'missing_save_version_or_revision_artifact');
  assert.equal(oracleVersionAndSave({ ...validEdit, aiChangeVisibleBeforeSave: undefined }).reason, 'missing_ai_change_visible_before_save');
  assert.equal(oracleVersionAndSave({ ...validEdit, aiChangeUndoableBeforeSave: undefined }).reason, 'missing_ai_change_undoable_before_save');
  assert.equal(oracleVersionAndSave({ ...validEdit, saveUsedCurrentBaseRevision: undefined }).reason, 'missing_save_used_current_base_revision');
  assert.equal(oracleVersionAndSave({ ...validEdit, doubleClickVersionsCreated: undefined }).reason, 'missing_double_click_versions_created');

  // FAIL when AI turn increments version count, changes revision, or emits save intent (G6-A03)
  assert.equal(oracleVersionAndSave({ ...validEdit, versionsAfterAiTurn: 2 }).reason, 'ai_turn_changed_version_count');
  assert.equal(oracleVersionAndSave({ ...validEdit, revisionAfterAiTurn: 'rev-2' }).reason, 'ai_turn_changed_document_revision');
  assert.equal(oracleVersionAndSave({ ...validEdit, saveIntentsDuringAiTurn: 1 }).reason, 'ai_turn_created_save_intent');

  // FAIL when explicit Save creates 0 or 2 versions, or fails Save invariants (G6-A04)
  assert.equal(oracleVersionAndSave({ ...validEdit, versionsAfterSave: 1 }).reason, 'explicit_save_version_delta_not_one');
  assert.equal(oracleVersionAndSave({ ...validEdit, versionsAfterSave: 3 }).reason, 'explicit_save_version_delta_not_one');
  assert.equal(oracleVersionAndSave({ ...validEdit, revisionAfterSave: 'rev-1' }).reason, 'explicit_save_did_not_advance_revision');
  assert.equal(oracleVersionAndSave({ ...validEdit, aiChangeVisibleBeforeSave: false }).reason, 'ai_change_not_visible_before_save');
  assert.equal(oracleVersionAndSave({ ...validEdit, aiChangeUndoableBeforeSave: false }).reason, 'ai_change_not_undoable_before_save');
  assert.equal(oracleVersionAndSave({ ...validEdit, saveUsedCurrentBaseRevision: false }).reason, 'save_did_not_use_current_base_revision');
  assert.equal(oracleVersionAndSave({ ...validEdit, doubleClickVersionsCreated: 1 }).reason, 'double_click_save_created_duplicate_version');
  assert.equal(oracleVersionAndSave({ ...validEdit, doubleClickVersionsCreated: 2 }).reason, 'double_click_save_created_duplicate_version');
});

test('oracleCapabilityAndToolSurface (G6-A06) enforces absent-not-disabled and bound-document tool exclusions', () => {
  const validSurface = {
    operation: 'edit',
    offeredTools: ['read_range', 'propose_operations'],
    controls: [{ capability: 'propose_operations', present: true, disabled: false }],
    executedTools: ['read_range'],
    unsupportedToolsOnHost: ['insert_chart'],
  };
  assert.equal(oracleCapabilityAndToolSurface(validSurface).status, VERDICT.PASS);

  // BLOCKED on missing offeredTools, missing controls, or missing executedTools on edit (R1-3)
  assert.equal(oracleCapabilityAndToolSurface(null).reason, 'missing_capability_surface_artifact');
  assert.equal(oracleCapabilityAndToolSurface({ ...validSurface, controls: undefined }).reason, 'missing_capability_controls_artifact');
  assert.equal(oracleCapabilityAndToolSurface({ ...validSurface, executedTools: undefined }).reason, 'missing_executed_tools_artifact');

  // FAIL when bound-document forbidden tool (`create_document`) is offered
  assert.equal(
    oracleCapabilityAndToolSurface({ ...validSurface, offeredTools: ['read_range', 'create_document'] }).reason,
    'forbidden_or_unsupported_tool_offered',
  );

  // FAIL when unsupported capability control is rendered disabled or present (G6-A06)
  assert.equal(
    oracleCapabilityAndToolSurface({
      ...validSurface,
      unsupportedToolsOnHost: ['edit_text'],
      controls: [{ capability: 'edit_text', present: true, disabled: true }],
    }).reason,
    'capability_control_disabled_instead_of_absent',
  );
  assert.equal(
    oracleCapabilityAndToolSurface({
      ...validSurface,
      unsupportedToolsOnHost: ['edit_text'],
      controls: [{ capability: 'edit_text', present: true, disabled: false }],
    }).reason,
    'unsupported_capability_control_present',
  );

  // FAIL when unsupported tool is executed
  assert.equal(
    oracleCapabilityAndToolSurface({
      ...validSurface,
      unsupportedToolsOnHost: ['edit_text'],
      executedTools: ['edit_text'],
    }).reason,
    'unsupported_tool_executed',
  );
});

test('oracleXlsxRead (X-R1, X-R2) and oracleXlsxEdit (X-E1) PASS faithful cases and FAIL/BLOCK every guard', () => {
  const xlsxTruth = computeTruth(parseXlsxWorkbookBytes(xlsxFixture.bytes));
  const q1AllVi = fmtVi(xlsxTruth.q1_revenue_all);
  const q1VisVi = fmtVi(xlsxTruth.q1_revenue_visible);
  const [bacShare, namShare, trungShare] = q1Shares();
  const bacVi = fmtVi(bacShare.revenue);
  const namVi = fmtVi(namShare.revenue);
  const trungVi = fmtVi(trungShare.revenue);

  const validXr1 = {
    rowId: 'X-R1',
    fixtureBytes: xlsxFixture.bytes,
    replyText: `Tổng doanh thu Q1 (gồm cả dòng 6 ẩn Q1-005) là ${q1AllVi} đồng (dòng 8 SUM = ${q1AllVi}, dòng 9 SUBTOTAL = ${q1VisVi}). Khu vực Bắc: ${bacVi}, Nam: ${namVi}, Trung: ${trungVi}.`,
  };
  assert.equal(oracleXlsxRead(validXr1).status, VERDICT.PASS);
  assert.equal(oracleXlsxRead({ fixtureBytes: xlsxFixture.bytes, replyText: '' }).reason, 'missing_xlsx_read_artifact');
  assert.equal(oracleXlsxRead({ ...validXr1, rowId: undefined }).reason, 'missing_xlsx_read_row_id');
  assert.equal(oracleXlsxRead({ ...validXr1, fixtureBytes: Buffer.from('not-xlsx') }).reason, 'xlsx_read_invalid_fixture_bytes');
  assert.equal(oracleXlsxRead({ ...validXr1, replyText: 'Tổng doanh thu Q1 là 99.999.999 đồng.' }).reason, 'xlsx_read_numeric_mismatch');
  assert.equal(oracleXlsxRead({ ...validXr1, replyText: `Tổng ${q1AllVi}, Bắc 1.000.000, Nam ${namVi}.` }).reason, 'xlsx_read_region_group_mismatch');
  assert.equal(
    oracleXlsxRead({ ...validXr1, replyText: `Tổng ${q1AllVi}, Bắc ${bacVi}, Nam ${namVi}.` }).reason,
    'xlsx_read_missing_coverage_or_hidden_total_note',
  );

  const validXr2 = {
    rowId: 'X-R2',
    fixtureBytes: xlsxFixture.bytes,
    replyText: `Cột Z có Q1-003/Q2-003 nhập số 10 thay vì 10% (phần trăm 0,1). Dòng 6 (Q1-005, Q2-005) đang ẩn nên SUBTOTAL dòng 9 là ${q1VisVi} khác SUM ${q1AllVi}. Các ô lỗi: #DIV/0!, #N/A, #REF!.`,
  };
  assert.equal(oracleXlsxRead(validXr2).status, VERDICT.PASS);
  assert.equal(oracleXlsxRead({ ...validXr2, replyText: 'Không giải thích cột giảm giá.' }).reason, 'xlsx_read_missing_z_meaning');
  assert.equal(
    oracleXlsxRead({ ...validXr2, replyText: 'Cột Z có số 10 khác 10% (phần trăm 0,1).' }).reason,
    'xlsx_read_missing_hidden_or_total_handling',
  );
  assert.equal(oracleXlsxRead({ ...validXr2, replyText: validXr2.replyText.replace('#REF!', '') }).reason, 'xlsx_read_error_cells_mismatch');

  // X-E1 edit tests
  const afterGood = buildEditedXlsxBytes(xlsxFixture.bytes);
  const validXe1 = {
    beforeBytes: xlsxFixture.bytes,
    afterBytes: afterGood,
    targetSheet: 'Doanh thu Q1',
    targetRange: 'AA2:AA7',
    panelFootprintText: 'Doanh thu Q1!AA2:AA7 (6 cells overwritten)',
  };
  assert.equal(oracleXlsxEdit(validXe1).status, VERDICT.PASS);
  assert.equal(oracleXlsxEdit({ beforeBytes: xlsxFixture.bytes }).reason, 'missing_xlsx_edit_bytes');
  assert.equal(oracleXlsxEdit({ ...validXe1, targetSheet: undefined }).reason, 'missing_xlsx_edit_target');
  assert.equal(oracleXlsxEdit({ ...validXe1, targetRange: undefined }).reason, 'missing_xlsx_edit_target');
  assert.equal(oracleXlsxEdit({ ...validXe1, afterBytes: Buffer.from('not-xlsx') }).reason, 'xlsx_edit_invalid_workbook_bytes');
  assert.equal(oracleXlsxEdit({ ...validXe1, targetRange: 'BAD_RANGE' }).reason, 'xlsx_edit_invalid_target_range');
  assert.equal(oracleXlsxEdit({ ...validXe1, targetSheet: 'Không tồn tại' }).reason, 'xlsx_edit_missing_target_sheet');
  assert.equal(
    oracleXlsxEdit({ ...validXe1, afterBytes: buildEditedXlsxBytes(xlsxFixture.bytes, { wrongValue: true }) }).reason,
    'xlsx_edit_target_cell_value_mismatch',
  );
  assert.equal(
    oracleXlsxEdit({ ...validXe1, afterBytes: buildEditedXlsxBytes(xlsxFixture.bytes, { wrongFormula: true }) }).reason,
    'xlsx_edit_target_formula_invalid',
  );
  assert.equal(
    oracleXlsxEdit({ ...validXe1, afterBytes: buildEditedXlsxBytes(xlsxFixture.bytes, { mutateCellA2: true }) }).reason,
    'xlsx_edit_unchanged_region_mutated',
  );
  assert.equal(oracleXlsxEdit({ ...validXe1, panelFootprintText: '' }).reason, 'xlsx_edit_missing_footprint_before_save');
});

test('w2l: X-R2 names which operand of the hidden-and-totals conjunction failed, without moving a threshold', () => {
  const truth = computeTruth(parseXlsxWorkbookBytes(xlsxFixture.bytes));
  const q1AllVi = fmtVi(truth.q1_revenue_all);
  const q1VisVi = fmtVi(truth.q1_revenue_visible);
  const base = {
    rowId: 'X-R2',
    fixtureBytes: xlsxFixture.bytes,
    replyText: `Cột Z có Q1-003/Q2-003 nhập số 10 thay vì 10% (phần trăm 0,1). Dòng 6 (Q1-005, Q2-005) đang ẩn nên SUBTOTAL dòng 9 là ${q1VisVi} khác SUM ${q1AllVi}. Các ô lỗi: #DIV/0!, #N/A, #REF!.`,
  };
  const allTrue = {
    zMeaning: true, hiddenRowId: true, subtotalOrVisibleTotal: true, allRowsTotal: true,
    errorCells: { '#DIV/0!': true, '#N/A': true, '#REF!': true },
  };
  const pass = oracleXlsxRead(base);
  assert.equal(pass.status, VERDICT.PASS);
  assert.deepEqual(pass.details.predicates, allTrue);

  // Each operand alone, with the others still true: the verdict is the old reason, the details say which.
  const noAllTotal = oracleXlsxRead({ ...base, replyText: base.replyText.replace(`SUM ${q1AllVi}`, 'SUM').replace(/\s*khác SUM\.?/, '') });
  assert.equal(noAllTotal.reason, 'xlsx_read_missing_hidden_or_total_handling');
  assert.deepEqual(noAllTotal.details.predicates, { ...allTrue, allRowsTotal: false });

  const noHidden = oracleXlsxRead({ ...base, replyText: base.replyText.replace('Dòng 6 (Q1-005, Q2-005) đang ẩn nên ', '') });
  assert.equal(noHidden.reason, 'xlsx_read_missing_hidden_or_total_handling');
  assert.deepEqual(noHidden.details.predicates, { ...allTrue, hiddenRowId: false });

  const noSubtotal = oracleXlsxRead({ ...base, replyText: base.replyText.replace(`SUBTOTAL dòng 9 là ${q1VisVi} khác `, 'dòng 9 khác ') });
  assert.equal(noSubtotal.reason, 'xlsx_read_missing_hidden_or_total_handling');
  assert.deepEqual(noSubtotal.details.predicates, { ...allTrue, subtotalOrVisibleTotal: false });

  // The error-cell operand is reported too, and it is evaluated even when an earlier operand already failed.
  const noRef = oracleXlsxRead({ ...base, replyText: base.replyText.replace('#REF!', '') });
  assert.equal(noRef.reason, 'xlsx_read_error_cells_mismatch');
  assert.deepEqual(noRef.details.predicates.errorCells, { '#DIV/0!': true, '#N/A': true, '#REF!': false });
  const noZ = oracleXlsxRead({ ...base, replyText: 'Không giải thích cột giảm giá. #DIV/0!' });
  assert.equal(noZ.reason, 'xlsx_read_missing_z_meaning');
  assert.equal(noZ.details.predicates.zMeaning, false);
  assert.deepEqual(noZ.details.predicates.errorCells, { '#DIV/0!': true, '#N/A': false, '#REF!': false });
});

// Real5 X-R2 reply of the web run (details.replyText of g7-08-real5/g7-08/X-R2-uniwork-web.json): it states
// that the SUM total row includes the hidden row and never prints the figure.
const REAL5_XR2_REPLY =
  'Trả lời:  Phát hiện: trong cột “Giảm giá (Z)”, số 10 là mức giảm 10% theo ghi chú của workbook, còn 10% được lưu là giá trị 0,1 và định dạng phần trăm. Ô trống nghĩa là không giảm giá.' +
  'Doanh thu Q1!F4: 10 — giảm 10%.Doanh thu Q1!F2: 10% — cũng giảm 10%.Doanh thu Q1!F5: trống — không giảm giá.' +
  'Dòng ẩn là dòng 6 ở cả hai sheet doanh thu: Q1-005 và Q2-005. SUM ở dòng tổng tính cả dòng ẩn; SUBTOTAL(109,...) ở dòng “không tính dòng ẩn” bỏ qua dòng ẩn.' +
  'Hai dòng tổng trên Doanh thu Q1: dòng 8 dùng SUM; dòng 9 dùng SUBTOTAL. Trên Doanh thu Q2: dòng 7 dùng SUM; dòng 8 dùng SUBTOTAL.' +
  'Các ô lỗi trong toàn workbook:Doanh thu Q2!H5: #DIV/0!Doanh thu Q2!I2: #N/ATổng hợp!B7: #REF!' +
  'Phạm vi kiểm tra là cả bốn sheet; không có dòng nào bị bỏ khỏi phạm vi. Các dòng ẩn đã được nhận diện như trên; không tính lại hay áp dụng quy tắc làm tròn. Kết quả phản ánh nội dung đang mở trong trình soạn thảo, gồm cả thay đổi chưa lưu.';

test('w2o: X-R2 accepts an explicit statement that the SUM total row includes the hidden row, not a vague SUM mention', () => {
  const base = { rowId: 'X-R2', fixtureBytes: xlsxFixture.bytes };
  const withSumSentence = (sumSentence) =>
    `Cột Z có số 10 thay vì 10% (phần trăm 0,1). Dòng 6 (Q1-005, Q2-005) đang ẩn. ${sumSentence} Các ô lỗi: #DIV/0!, #N/A, #REF!.`;
  const verdict = (replyText) => oracleXlsxRead({ ...base, replyText });

  // The real web reply passes.
  const real = verdict(REAL5_XR2_REPLY);
  assert.equal(real.status, VERDICT.PASS);
  assert.equal(real.details.predicates.allRowsTotal, true);

  // vi and en positives.
  assert.equal(verdict(withSumSentence('SUM dòng 8 tính cả dòng ẩn; SUBTOTAL dòng 9 bỏ qua dòng ẩn.')).status, VERDICT.PASS);
  assert.equal(verdict(withSumSentence('SUM ở dòng 8 bao gồm dòng ẩn, còn SUBTOTAL dòng 9 thì không.')).status, VERDICT.PASS);
  assert.equal(verdict(withSumSentence('The SUM in row 8 includes the hidden row; SUBTOTAL in row 9 ignores it.')).status, VERDICT.PASS);

  // Negatives: each fails on the allRowsTotal operand only.
  const sumOnly = verdict(withSumSentence('Dòng 8 dùng SUM; dòng 9 dùng SUBTOTAL.'));
  assert.equal(sumOnly.reason, 'xlsx_read_missing_hidden_or_total_handling');
  assert.equal(sumOnly.details.predicates.allRowsTotal, false);
  assert.equal(sumOnly.details.predicates.subtotalOrVisibleTotal, true);

  const sumExcludes = verdict(withSumSentence('SUM dòng 8 không tính dòng ẩn; SUBTOTAL dòng 9 là tổng đã lọc.'));
  assert.equal(sumExcludes.reason, 'xlsx_read_missing_hidden_or_total_handling');
  assert.equal(sumExcludes.details.predicates.allRowsTotal, false);

  const sumExcludesEn = verdict(withSumSentence('The SUM in row 8 excludes the hidden row; SUBTOTAL in row 9 is filtered.'));
  assert.equal(sumExcludesEn.details.predicates.allRowsTotal, false);

  const sumIgnoresNot = verdict(withSumSentence('SUM dòng 8 không tính cả dòng ẩn; SUBTOTAL dòng 9 là tổng đã lọc.'));
  assert.equal(sumIgnoresNot.details.predicates.allRowsTotal, false);

  const noSum = verdict(withSumSentence('Dòng 9 dùng SUBTOTAL(109,...) nên bỏ qua dòng ẩn, dòng tổng còn lại tính cả dòng ẩn.'));
  assert.equal(noSum.reason, 'xlsx_read_missing_hidden_or_total_handling');
  assert.equal(noSum.details.predicates.allRowsTotal, false);

  // The SUBTOTAL half of the sentence must not lend its words to the SUM clause.
  const subtotalIncludes = verdict(withSumSentence('SUM dòng 8 là tổng; SUBTOTAL dòng 9 tính cả dòng ẩn.'));
  assert.equal(subtotalIncludes.details.predicates.allRowsTotal, false);
});

function rewriteXlsxParts(baseBytes, mutateParts) {
  const entries = readZipEntries(baseBytes);
  const parts = Object.fromEntries(entries.map((e) => [e.name, e.data]));
  const xmlParts = {
    sheet1: parts['xl/worksheets/sheet1.xml'].toString('utf8'),
    sheet2: parts['xl/worksheets/sheet2.xml'].toString('utf8'),
    sheet3: parts['xl/worksheets/sheet3.xml'].toString('utf8'),
  };
  mutateParts(xmlParts);
  parts['xl/worksheets/sheet1.xml'] = Buffer.from(xmlParts.sheet1, 'utf8');
  parts['xl/worksheets/sheet2.xml'] = Buffer.from(xmlParts.sheet2, 'utf8');
  parts['xl/worksheets/sheet3.xml'] = Buffer.from(xmlParts.sheet3, 'utf8');
  return zipStore(ooxmlEntries(parts));
}

test('w3c: oracleXlsxEdit tolerates <= 1e-9 float noise on unchanged numeric caches, fails real/error changes, and lists up to 20 mutated cells', () => {
  const afterGood = buildEditedXlsxBytes(xlsxFixture.bytes);
  const baseObserved = {
    beforeBytes: xlsxFixture.bytes,
    afterBytes: afterGood,
    targetSheet: 'Doanh thu Q1',
    targetRange: 'AA2:AA7',
    panelFootprintText: 'Doanh thu Q1!AA2:AA7 (6 cells overwritten)',
  };

  // 1. Float noise only (relative or absolute difference <= 1e-9, same f, same t) counts as unchanged.
  const afterFloatNoise = rewriteXlsxParts(afterGood, (xml) => {
    // w3b Tổng hợp!E5: SUM(E2:E4) cached value 1 -> 0.9999999999999999 (diff ~1.11e-16 <= 1e-9)
    xml.sheet3 = xml.sheet3.replace(
      '<c r="E5" s="4"><f>SUM(E2:E4)</f><v>1</v></c>',
      '<c r="E5" s="4"><f>SUM(E2:E4)</f><v>0.9999999999999999</v></c>',
    );
    // Large number with relative difference ~4.53e-10 <= 1e-9 (absolute difference 0.01 > 1e-9)
    xml.sheet3 = xml.sheet3.replace(
      '<c r="B5" s="5"><f>SUM(B2:B4)</f><v>22060000</v></c>',
      '<c r="B5" s="5"><f>SUM(B2:B4)</f><v>22060000.01</v></c>',
    );
    // Small number with absolute difference 5e-10 <= 1e-9 (relative difference 5e-9 > 1e-9)
    xml.sheet1 = xml.sheet1.replace(
      '<c r="F2" s="3"><v>0.1</v></c>',
      '<c r="F2" s="3"><v>0.1000000005</v></c>',
    );
  });
  assert.equal(oracleXlsxEdit({ ...baseObserved, afterBytes: afterFloatNoise }).status, VERDICT.PASS);

  // 2. A real numeric change (> 1e-9 relative and absolute) still fails.
  const afterRealNumericChange = rewriteXlsxParts(afterGood, (xml) => {
    xml.sheet3 = xml.sheet3.replace(
      '<c r="E5" s="4"><f>SUM(E2:E4)</f><v>1</v></c>',
      '<c r="E5" s="4"><f>SUM(E2:E4)</f><v>1.000000002</v></c>',
    );
  });
  const numericFail = oracleXlsxEdit({ ...baseObserved, afterBytes: afterRealNumericChange });
  assert.equal(numericFail.status, VERDICT.FAIL);
  assert.equal(numericFail.reason, 'xlsx_edit_unchanged_region_mutated');
  assert.deepEqual(numericFail.details.mutatedCells, [
    {
      sheet: 'Tổng hợp',
      ref: 'E5',
      before: { v: 1, f: 'SUM(E2:E4)', t: 'n' },
      after: { v: 1.000000002, f: 'SUM(E2:E4)', t: 'n' },
    },
  ]);

  // 3. Error cells losing t="e" / v still fail, and all mutated cells are listed (while float noise on E5 is ignored).
  const afterW3bSave = rewriteXlsxParts(afterGood, (xml) => {
    xml.sheet2 = xml.sheet2
      .replace(
        "<c r=\"I2\" t=\"e\"><f>VLOOKUP(A2,'Doanh thu Q1'!$A$2:$G$7,7,FALSE)</f><v>#N/A</v></c>",
        "<c r=\"I2\"><f>VLOOKUP(A2,'Doanh thu Q1'!$A$2:$G$7,7,FALSE)</f></c>",
      )
      .replace(
        '<c r="H5" t="e"><f>G5/D5</f><v>#DIV/0!</v></c>',
        '<c r="H5"><f>G5/D5</f></c>',
      );
    xml.sheet3 = xml.sheet3
      .replace(
        '<c r="E5" s="4"><f>SUM(E2:E4)</f><v>1</v></c>',
        '<c r="E5" s="4"><f>SUM(E2:E4)</f><v>0.9999999999999999</v></c>',
      )
      .replace(
        '<c r="B7" t="e"><f>#REF!</f><v>#REF!</v></c>',
        '<c r="B7"><f>#REF!</f></c>',
      );
  });
  const errorFail = oracleXlsxEdit({ ...baseObserved, afterBytes: afterW3bSave });
  assert.equal(errorFail.status, VERDICT.FAIL);
  assert.equal(errorFail.reason, 'xlsx_edit_unchanged_region_mutated');
  assert.deepEqual(errorFail.details.mutatedCells, [
    {
      sheet: 'Doanh thu Q2',
      ref: 'I2',
      before: { v: '#N/A', f: "VLOOKUP(A2,'Doanh thu Q1'!$A$2:$G$7,7,FALSE)", t: 'e' },
      after: { v: null, f: "VLOOKUP(A2,'Doanh thu Q1'!$A$2:$G$7,7,FALSE)", t: 'n' },
    },
    {
      sheet: 'Doanh thu Q2',
      ref: 'H5',
      before: { v: '#DIV/0!', f: 'G5/D5', t: 'e' },
      after: { v: null, f: 'G5/D5', t: 'n' },
    },
    {
      sheet: 'Tổng hợp',
      ref: 'B7',
      before: { v: '#REF!', f: '#REF!', t: 'e' },
      after: { v: null, f: '#REF!', t: 'n' },
    },
  ]);

  // 4. FAIL details list EVERY mutated cell, capped at 20.
  const afterManyMutations = rewriteXlsxParts(afterGood, (xml) => {
    // Mutate 25 numeric cells across sheet1 and sheet2
    let count = 0;
    const bumpNumeric = (s) =>
      s.replace(/<c r="([D-G][2-7])"([^>]*)>((?:<f>[\s\S]*?<\/f>)?)<v>(\d+)<\/v><\/c>/g, (full, ref, attrs, fXml, vStr) => {
        if (count >= 25) return full;
        count += 1;
        return `<c r="${ref}"${attrs}>${fXml}<v>${Number(vStr) + 999}</v></c>`;
      });
    xml.sheet1 = bumpNumeric(xml.sheet1);
    xml.sheet2 = bumpNumeric(xml.sheet2);
  });
  const manyFail = oracleXlsxEdit({ ...baseObserved, afterBytes: afterManyMutations });
  assert.equal(manyFail.status, VERDICT.FAIL);
  assert.equal(manyFail.reason, 'xlsx_edit_unchanged_region_mutated');
  assert.equal(manyFail.details.mutatedCells.length, 20);
  for (const item of manyFail.details.mutatedCells) {
    assert.equal(typeof item.sheet, 'string');
    assert.equal(typeof item.ref, 'string');
    assert.deepEqual(Object.keys(item.before), ['v', 'f', 't']);
    assert.deepEqual(Object.keys(item.after), ['v', 'f', 't']);
    assert.equal(item.after.v, item.before.v + 999);
  }
});

test('oraclePdfRead (F-R1) and oraclePdfEdit (F-E1) PASS faithful cases and FAIL/BLOCK every guard', () => {
  const validPdfRead = {
    fixtureBytes: pdfFixture.bytes,
    replyText:
      'Trang 1: Hóa đơn HD-2026-0001 ngày 01/10/2026 của Công ty TNHH Mẫu An Bình, tổng thanh toán 1.650.000 đồng.',
  };
  assert.equal(oraclePdfRead(validPdfRead).status, VERDICT.PASS);
  assert.equal(oraclePdfRead({ fixtureBytes: pdfFixture.bytes, replyText: '' }).reason, 'missing_pdf_read_artifact');
  assert.equal(oraclePdfRead({ ...validPdfRead, fixtureBytes: Buffer.from('not-pdf') }).reason, 'pdf_read_invalid_fixture_bytes');
  assert.equal(oraclePdfRead({ ...validPdfRead, scannedPageWithoutOcr: true }).reason, 'pdf_scanned_page_faked');
  assert.equal(
    oraclePdfRead({ ...validPdfRead, replyText: 'HD-2026-0001 01/10/2026 Công ty TNHH Mẫu An Bình 1.650.000' }).reason,
    'pdf_read_missing_page_anchor',
  );
  assert.equal(oraclePdfRead({ ...validPdfRead, replyText: 'Trang 1: thiếu mã hóa đơn' }).reason, 'pdf_read_missing_extracted_text');

  // F-E1 BLOCKED when artifact or capability flag missing (R1-2)
  assert.equal(oraclePdfEdit(null).reason, 'missing_pdf_edit_artifact');
  const missingFlag = oraclePdfEdit({ beforeLines: ['a'], afterLines: ['b'] });
  assert.equal(missingFlag.status, VERDICT.BLOCKED);
  assert.equal(missingFlag.reason, 'missing_pdf_text_edit_capability_flag');

  // F-E1 when host lacks pdfium text edit: BLOCKED (77) if edit tools are absent, FAIL if offered/disabled
  const blockedNoPdfium = oraclePdfEdit({
    hostSupportsPdfTextEdit: false,
    offeredTools: ['read_pages', 'get_outline'],
    controls: [],
    executedTools: [],
  });
  assert.equal(blockedNoPdfium.status, VERDICT.BLOCKED);
  assert.equal(blockedNoPdfium.exitCode, 77);
  assert.equal(blockedNoPdfium.reason, 'missing: ẩn công cụ sửa text khi pdfium không có (docs/office/g5g6g7/genoffice-tools.md:747)');

  const failLeakedEditTool = oraclePdfEdit({
    hostSupportsPdfTextEdit: false,
    offeredTools: ['read_pages', 'edit_text'],
  });
  assert.equal(failLeakedEditTool.status, VERDICT.FAIL);

  // F-E1 when host supports PDF text edit
  const extracted = extractPdfTextFromBytes(pdfFixture.bytes);
  const patchedLines = extracted.lines.map((line) =>
    line === 'Số hóa đơn: HD-2026-0001' ? 'Số hóa đơn: HD-2026-0001-AI' : line,
  );
  const validPdfEdit = {
    hostSupportsPdfTextEdit: true,
    beforeLines: extracted.lines,
    afterLines: patchedLines,
    targetText: 'Số hóa đơn: HD-2026-0001',
    expectedPatchText: 'Số hóa đơn: HD-2026-0001-AI',
  };
  assert.equal(oraclePdfEdit(validPdfEdit).status, VERDICT.PASS);
  assert.equal(oraclePdfEdit({ hostSupportsPdfTextEdit: true }).reason, 'missing_pdf_edit_bytes_or_extraction');
  assert.equal(oraclePdfEdit({ ...validPdfEdit, targetText: undefined }).reason, 'missing_pdf_target_or_expected_patch_text');
  assert.equal(oraclePdfEdit({ ...validPdfEdit, afterLines: patchedLines.slice(0, -1) }).reason, 'pdf_page_or_line_count_changed');
  assert.equal(oraclePdfEdit({ ...validPdfEdit, afterLines: extracted.lines }).reason, 'pdf_target_text_unchanged_or_wrong');
  assert.equal(
    oraclePdfEdit({ ...validPdfEdit, afterLines: patchedLines.map((l, idx) => (idx === 0 ? 'Bị sửa nhầm' : l)) }).reason,
    'pdf_extraction_outside_patch_modified',
  );
  assert.equal(
    oraclePdfEdit({ ...validPdfEdit, beforeLines: ['Dòng khác'], afterLines: ['Dòng khác'] }).reason,
    'pdf_target_text_not_found',
  );

  // w3e: compressed PDF variant (ObjStm Pages + FlateDecode content/CMap + TJ/Tm/Td + fallback font run for -AI)
  const buildCompressedPdf = ({ pageCount = 1, patchInvoice = false, dropLastLine = false, mutateFirstLine = false } = {}) => {
    const raw = Buffer.from(pdfFixture.bytes).toString('latin1');
    const extraPages = Array.from({ length: Math.max(0, pageCount - 1) }, (_, i) => 24 + i);
    const kids = [3, ...extraPages].map((id) => `${id} 0 R`).join(' ');
    const hdr = '2 0\n';
    const objStm = Buffer.concat([deflateSync(Buffer.from(`${hdr}<< /Count ${pageCount} /Kids [${kids}] /Type /Pages >>`, 'latin1')), Buffer.from('\n')]);
    const chunks = [
      Buffer.from('%PDF-1.7\n%\xe2\xe3\xcf\xd3\n', 'latin1'),
      Buffer.from(`20 0 obj\n<< /Type /ObjStm /N 1 /First ${hdr.length} /Filter /FlateDecode /Length ${objStm.length} >>\nstream\n`, 'latin1'),
      objStm,
      Buffer.from('\nendstream\nendobj\n', 'latin1'),
    ];
    for (const m of raw.matchAll(/(\d+)\s+0\s+obj\n([\s\S]*?)\nendobj/g)) {
      const [id, body] = [Number(m[1]), m[2]];
      if (id === 2) continue;
      const [sIdx, eIdx] = [body.indexOf('>>\nstream\n'), body.lastIndexOf('\nendstream')];
      if (sIdx < 0 || eIdx < 0) {
        chunks.push(Buffer.from(`${id} 0 obj\n${body}\nendobj\n`, 'latin1'));
        continue;
      }
      const dict = body.slice(2, sIdx).replace(/\/Length\s+\d+/, '').trim();
      let sBody = body.slice(sIdx + 10, eIdx);
      if (id === 4) {
        let idx = 0;
        sBody = sBody.replace(/BT \/F(\d+) ([\d.]+) Tf 1 0 0 1 ([\d.-]+) ([\d.-]+) Tm <([0-9A-Fa-f]+)> Tj ET/g, (_, f, sz, x, y, hex) => {
          idx += 1;
          if (dropLastLine && idx === 35) return '';
          const h = mutateFirstLine && idx === 1 ? hex.slice(0, -4) : hex;
          const mid = Math.floor(h.length / 8) * 4;
          if (patchInvoice && idx === 2) {
            return `q 1 0 0 1 ${x} ${y} cm BT\n1 0 0 1 0 0 Tm\n/F${f} ${sz} Tf\n0 Tr\n[<${h.slice(0, mid)}> 0 <${h.slice(mid)}>] TJ\nET Q\nq 1 0 0 1 188.138 ${y} cm BT\n0 0 Td\n/FXF3 ${sz} Tf\n<000100020003> Tj\nET Q`;
          }
          return `BT\n/F${f} ${sz} Tf\n${x} ${y} Td\n[<${h.slice(0, mid)}> 0 <${h.slice(mid)}>] TJ\nET`;
        });
      }
      const deflated = Buffer.concat([deflateSync(Buffer.from(sBody, 'latin1')), Buffer.from('\n')]);
      chunks.push(
        Buffer.from(`${id} 0 obj\n<< ${dict} /Filter /FlateDecode /Length ${deflated.length} >>\nstream\n`, 'latin1'),
        deflated,
        Buffer.from('\nendstream\nendobj\n', 'latin1'),
      );
    }
    if (patchInvoice) {
      const cmap3 = deflateSync(Buffer.from('begincmap\n1 beginbfrange\n<0001> <0003> [<002D> <0041> <0049>]\nendbfrange\nendcmap', 'latin1'));
      chunks.push(
        Buffer.from('21 0 obj\n<< /Type /Font /Subtype /Type0 /ToUnicode 22 0 R >>\nendobj\n', 'latin1'),
        Buffer.from(`22 0 obj\n<< /Filter /FlateDecode /Length ${cmap3.length} >>\nstream\n`, 'latin1'),
        cmap3,
        Buffer.from('\nendstream\nendobj\n', 'latin1'),
        Buffer.from('23 0 obj\n<< /Resources << /Font << /FXF3 21 0 R >> >> >>\nendobj\n', 'latin1'),
      );
    }
    for (const id of extraPages) {
      chunks.push(Buffer.from(`${id} 0 obj\n<< /Type /Page /Parent 2 0 R >>\nendobj\n`, 'latin1'));
    }
    chunks.push(Buffer.from('trailer\n<< /Root 1 0 R >>\n%%EOF\n', 'latin1'));
    return Buffer.concat(chunks);
  };

  const compUnedited = extractPdfTextFromBytes(buildCompressedPdf());
  assert.equal(compUnedited.pageCount, extracted.pageCount);
  assert.deepEqual(compUnedited.lines, extracted.lines);

  const baseCompEdit = {
    hostSupportsPdfTextEdit: true,
    beforeBytes: pdfFixture.bytes,
    afterBytes: buildCompressedPdf({ patchInvoice: true }),
    targetText: 'Số hóa đơn: HD-2026-0001',
    expectedPatchText: 'Số hóa đơn: HD-2026-0001-AI',
  };
  assert.equal(oraclePdfEdit(baseCompEdit).status, VERDICT.PASS);
  assert.equal(oraclePdfEdit({ ...baseCompEdit, afterBytes: buildCompressedPdf({ patchInvoice: true, pageCount: 2 }) }).reason, 'pdf_page_or_line_count_changed');
  assert.equal(oraclePdfEdit({ ...baseCompEdit, afterBytes: buildCompressedPdf({ patchInvoice: true, dropLastLine: true }) }).reason, 'pdf_page_or_line_count_changed');
  assert.equal(oraclePdfEdit({ ...baseCompEdit, afterBytes: buildCompressedPdf({ patchInvoice: false }) }).reason, 'pdf_target_text_unchanged_or_wrong');
  assert.equal(oraclePdfEdit({ ...baseCompEdit, afterBytes: buildCompressedPdf({ patchInvoice: true, mutateFirstLine: true }) }).reason, 'pdf_extraction_outside_patch_modified');
});

